package dev.sablelife.testing;
import dev.sablelife.SableLife;
import dev.sablelife.heart.*;
import dev.sablelife.module.*;
import dev.sablelife.attack.*;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
@GameTestHolder("sablelife_control_tests") @PrefixGameTestTemplate(false)
public final class HitHealthGameTests {
 private static HeartBlockEntity body(GameTestHelper h,BlockPos pos){var l=h.getLevel();l.setBlockAndUpdate(pos,SableLife.HEART.get().defaultBlockState());l.setBlockAndUpdate(pos.north(),Blocks.IRON_BLOCK.defaultBlockState());var b=SubLevelAssemblyHelper.assembleBlocks(l,pos,List.of(pos,pos.north()),new BoundingBox3i(pos.getX(),pos.getY(),pos.getZ()-1,pos.getX(),pos.getY(),pos.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(b.getPlot().getCenterBlock());c.configure(100,60);return c;}
 private static HeartBlockEntity core(GameTestHelper h){return body(h,h.absolutePos(new BlockPos(3,40,3)));}
 private static VirtualModule attack(HeartBlockEntity c,String type){var m=c.modules().add(type);m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.EAST)));m.edit("trigger",2,"");m.edit("channel",63,"");return m;}
 private static VirtualModule counter(HeartBlockEntity c,int threshold){var m=c.modules().add("hit_counter");m.edit("hitThreshold",threshold,"");return m;}
 private static int count(HeartBlockEntity c,VirtualModule m){return c.modules().hitCounter.snapshot(m.id()).getInt("Count");}
 private static net.minecraft.world.entity.animal.Cow cow(GameTestHelper h){var e=EntityType.COW.create(h.getLevel());e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);e.setHealth(100);return e;}
 private static int channel(HeartBlockEntity c){int ch=c.wireless().add();c.wireless().channel(ch).set(0,1);c.wireless().channel(ch).set(6,3);return ch;}
 @GameTest(template="combat",batch="hit_heal_link",timeoutTicks=40)
 public static void ActualDamageThresholdHealsOnceAndIgnoresInvulnerableZeroAndAbsorption(GameTestHelper h){var c=core(h);var weapon=attack(c,"melee");var count=counter(c,3);int ch=channel(c);count.edit("hitChannel",ch+1,"");count.edit("hitPulse",3,"");var heal=c.modules().add("health_adjustment");heal.edit("trigger",2,"");heal.edit("channel",ch,"");heal.edit("healthAmount",10,"");c.tryActivate(TestActors.creative(h.getLevel()));c.adjustOwnHealth(-30,false);var target=cow(h);var source=ModuleDamage.physical(h.getLevel());
  target.setInvulnerable(true);ModuleDamage.hurt(target,source,4,c,weapon);target.setInvulnerable(false);ModuleDamage.hurt(target,source,0,c,weapon);target.getAttribute(Attributes.MAX_ABSORPTION).setBaseValue(20);target.setAbsorptionAmount(10);ModuleDamage.hurt(target,source,2,c,weapon);h.assertTrue(count(c,count)==0,"Non-HP hit counted");target.setAbsorptionAmount(0);
  for(int i=0;i<3;i++)ModuleDamage.hurt(target,source,2,c,weapon);h.assertTrue(count(c,count)==3,"Successful native hits did not reach threshold");
  h.runAfterDelay(2,()->{h.assertTrue(c.health().current()==80,"Threshold pulse failed to heal exactly once");ModuleDamage.hurt(target,source,2,c,weapon);});
  h.runAfterDelay(7,()->{h.assertTrue(c.health().current()==80&&count(c,count)==0,"Held pulse healed repeatedly or failed to reset");c.resetForCreative(TestActors.creative(h.getLevel()));target.discard();h.succeed();});
 }
 @GameTest(template="combat",batch="hit_source_identity")
 public static void SourceSelectorSurvivesReorderSaveAndUnbindsPortablePreset(GameTestHelper h){var c=core(h);var a=attack(c,"melee");var b=attack(c,"flame");var m=counter(c,5);var actor=TestActors.creative(h.getLevel());actor.setPos(dev.sablelife.compat.sable.SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter()));var menu=new HeartDashboardMenu(1,actor.getInventory(),c);h.assertTrue(menu.action(actor,c.modules().revision(),m.id(),"edit","hitSource",2,""),"Source selection rejected");c.modules().reorder(b.id(),-1);h.assertTrue(m.hitSourceId().equals(b.id())&&VirtualModule.load(m.save()).hitSourceId().equals(b.id()),"Source lost identity on save/reorder");var preset=ModulePreset.create(m.save());h.assertTrue(preset.hitSourceId()==null&&preset.value("hitChannel")==0,"Portable preset retained foreign source");c.tryActivate(actor);var target=cow(h);ModuleDamage.hurt(target,ModuleDamage.physical(h.getLevel()),2,c,a);h.assertTrue(count(c,m)==0,"Unselected source counted");ModuleDamage.hurt(target,ModuleDamage.physical(h.getLevel()),2,c,b);h.assertTrue(count(c,m)==1,"Selected source not counted");c.modules().remove(b.id());c.modules().hitCounter.record(c,b.id(),2);h.assertTrue(count(c,m)==1,"Removed attack source counted");c.resetForCreative(actor);target.discard();h.succeed();}
 @GameTest(template="combat",batch="self_hp_rules")
 public static void OwnDrainBypassesDefenseButNotDeathSafetyOrHealthCap(GameTestHelper h){var c=core(h);var incoming=c.modules().add("damage_accumulation");incoming.edit("accumThreshold",1,"");c.tryActivate(TestActors.creative(h.getLevel()));h.assertTrue(c.adjustOwnHealth(-1000,false)&&c.health().current()==1&&c.health().state()==HeartState.ALIVE,"Safe drain killed core");h.assertTrue(!c.modules().damageAccumulation.snapshot(incoming,c).getBoolean("High")&&!c.modules().snapshot(c,true).getBoolean("BgmStarted"),"Self drain was incoming attack");c.adjustOwnHealth(1000,false);h.assertTrue(c.health().current()==100,"Heal exceeded maximum");h.assertTrue(!c.adjustOwnHealth(Double.NaN,true),"NaN adjustment accepted");c.adjustOwnHealth(-1000,true);h.assertTrue(c.health().state()==HeartState.DYING&&c.health().current()==0&&!c.adjustOwnHealth(50,false),"Lethal drain bypassed normal death or dead core healed");h.succeed();}
 @GameTest(template="combat",batch="self_hp_periodic",timeoutTicks=30)
 public static void PercentPeriodicAndOnceEdgesUseIndependentClocks(GameTestHelper h){var c=core(h);var m=c.modules().add("health_adjustment");m.edit("healthAmount",5,"");m.edit("healthUnits",1,"");m.edit("healthMode",1,"");m.edit("healthInterval",2,"");c.tryActivate(TestActors.creative(h.getLevel()));c.adjustOwnHealth(-50,false);c.modules().tick(c);h.assertTrue(c.health().current()==55,"Periodic failed immediate percent adjustment");
  h.runAfterDelay(5,()->{h.assertTrue(c.health().current()==65,"Periodic cadence drifted");m.edit("enabled",0,"");});h.runAfterDelay(7,()->{h.assertTrue(c.health().current()==65,"Disabled periodic healed");m.edit("healthMode",0,"");m.edit("enabled",1,"");});h.runAfterDelay(10,()->{h.assertTrue(c.health().current()==70,"Once edge repeated under Always");c.resetForCreative(TestActors.creative(h.getLevel()));h.succeed();});}
 @GameTest(template="combat",batch="hit_projectile")
 public static void ArrowNativeHitReloadAndShotBlastCreditTheirOriginalModule(GameTestHelper h)throws Exception{var c=core(h);var a=attack(c,"arrow");var g=attack(c,"gun");var m=counter(c,20);c.tryActivate(TestActors.creative(h.getLevel()));var target=cow(h);var arrow=new ModuleArrow(SableLife.MODULE_ARROW.get(),h.getLevel());arrow.configure(a);arrow.setBaseDamage(2);arrow.setDeltaMovement(1,0,0);AttackHitCredit.attach(arrow,c,a);var saved=arrow.saveWithoutId(new CompoundTag());var loaded=new ModuleArrow(SableLife.MODULE_ARROW.get(),h.getLevel());loaded.load(saved);var hit=ModuleArrow.class.getDeclaredMethod("onHitEntity",EntityHitResult.class);hit.setAccessible(true);hit.invoke(loaded,new EntityHitResult(target));h.assertTrue(count(c,m)==1,"Native arrow did not credit exactly once after reload");var shot=new ModuleShot(h.getLevel(),new Vec3(0,40,0),new Vec3(1,0,0),g,c);ModuleDamage.hurt(target,h.getLevel().damageSources().thrown(shot,null),2);h.assertTrue(count(c,m)==2,"Shot damage not credited");g.edit("explode",1,"");g.edit("blastDamage",3,"");var blastTarget=cow(h);var blastPoint=dev.sablelife.compat.sable.SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter()).add(5,0,0);blastTarget.setPos(blastPoint);h.getLevel().addFreshEntity(blastTarget);ModuleBlast.explode(h.getLevel(),shot,blastPoint,ModuleBlast.settings(g));h.assertTrue(count(c,m)==3,"Actual projectile blast did not credit one target");blastTarget.discard();var other=coreDamageProxy(h,c);ModuleDamage.hurt(other,ModuleDamage.physical(h.getLevel()),2,c,g);h.assertTrue(count(c,m)==4,"Mechanical life target not credited");var bodyVictim=body(h,h.absolutePos(new BlockPos(13,40,13)));bodyVictim.tryActivate(TestActors.creative(h.getLevel()));var bodyArrow=new ModuleArrow(SableLife.MODULE_ARROW.get(),h.getLevel());bodyArrow.setBaseDamage(2);bodyArrow.setDeltaMovement(1,0,0);AttackHitCredit.attach(bodyArrow,c,a);var event=new net.neoforged.neoforge.event.entity.ProjectileImpactEvent(bodyArrow,new BlockHitResult(bodyVictim.getBlockPos().getCenter(),Direction.WEST,bodyVictim.getBlockPos(),false));dev.sablelife.combat.BodyCombat.onProjectileImpact(event);dev.sablelife.combat.BodyCombat.onProjectileImpact(event);h.assertTrue(count(c,m)==5,"Arrow-to-real-body missed or duplicated credit");bodyVictim.resetForCreative(TestActors.creative(h.getLevel()));c.resetForCreative(TestActors.creative(h.getLevel()));target.discard();loaded.discard();shot.discard();h.succeed();}
 private static net.minecraft.world.entity.LivingEntity coreDamageProxy(GameTestHelper h,HeartBlockEntity attacker){var target=body(h,h.absolutePos(new BlockPos(9,40,9)));target.tryActivate(TestActors.creative(h.getLevel()));return ModuleTargets.query(h.getLevel(),attacker.creatureId(),dev.sablelife.ownership.LoadedCoreIndex.bounds(target).inflate(1),x->x.getUUID().equals(target.creatureId())).stream().filter(e->e instanceof ModuleTargets.LifeTarget).findFirst().orElseThrow();}
 @GameTest(template="combat",batch="self_move_cost",timeoutTicks=40)
 public static void MoveSetOnceDrainRunsOncePerActionWindowAndRestartsNextMove(GameTestHelper h){var c=core(h);var cost=c.modules().add("health_adjustment");cost.edit("healthAmount",-5,"");var table=c.modules().add("move_set");table.moveSet().edit("add",0,"",c.modules());table.moveSet().edit("action_add",0,"0|"+cost.id(),c.modules());table.moveSet().edit("action_duration",.1,"0|0",c.modules());var cfg=table.moveSet().get(0).config();cfg.edit("dispatchBusy",2,"");cfg.edit("dispatchRest",1,"");cfg.edit("dispatchCooldown",0,"");cfg.edit("target",1,"");cfg.edit("dispatchNear",0,"");cfg.edit("dispatchFar",16,"");var target=cow(h);target.setPos(dev.sablelife.compat.sable.SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter()).add(2,0,0));h.getLevel().addFreshEntity(target);c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);h.assertTrue(c.health().current()==95,"Move did not pay initial cost");h.runAfterDelay(1,()->h.assertTrue(c.health().current()==95,"One window paid cost twice"));h.runAfterDelay(4,()->{h.assertTrue(c.health().current()==90,"Next Move Set activation failed to pay cost");c.resetForCreative(TestActors.creative(h.getLevel()));target.discard();h.succeed();});}
 @GameTest(template="combat",batch="hit_gap",timeoutTicks=25)
 public static void CountIntervalIsSharedAndTriggerOffClearsPartialProgress(GameTestHelper h){var c=core(h);var weapon=attack(c,"pulse");var m=counter(c,10);m.edit("hitGap",4,"");c.tryActivate(TestActors.creative(h.getLevel()));var target=cow(h);for(int i=0;i<5;i++)ModuleDamage.hurt(target,ModuleDamage.physical(h.getLevel()),1,c,weapon);h.assertTrue(count(c,m)==1,"Shared same-tick gap not enforced");h.runAfterDelay(5,()->{ModuleDamage.hurt(target,ModuleDamage.physical(h.getLevel()),1,c,weapon);h.assertTrue(count(c,m)==2,"Interval did not rearm");m.edit("enabled",0,"");c.modules().tick(c);h.assertTrue(count(c,m)==0,"Disabled counter retained progress");c.resetForCreative(TestActors.creative(h.getLevel()));target.discard();h.succeed();});}

}
